// ============================================================
// PriceScope — site icons (favicon / apple-touch-icon / OG image)
//
// ★ 为什么是 base64 内嵌而不是静态资源：
//   本站是纯 Workers SSR，没有 [assets] 目录，所有响应都由 JS 生成。
//   图标若放外部域名，会因为跨域缓存/可用性而牵连本站；
//   内嵌后本站自包含，不依赖任何第三方。
//
// ★ 为什么 base64 要切成短行（joinB64）：
//   历史上这里是一整行 16.9 万字符，导致 GitHub 网页上传器处理失败
//   （CF 仍能部署成功，因为文件本体没坏，只是网页上传器扛不住超长单行）。
//   现按 1200 字符一行分块，运行时拼回。导出变量名与值完全不变。
//
// ★ A15 体积优化（2026-10-24）：271KB → 约 97KB
//   OG 图 PNG(127KB) → JPEG q85(51KB)，PSNR 36.1dB 视觉无损；
//   apple-touch / logo 做 200 色量化；favicon.ico 只保留 16/32 两尺寸。
//
//   修改方式：替换下方 base64 分块即可，不要把 PNG/JPEG 直接塞进 JS。
// ============================================================

// ★ 分块拼接：把长 base64 拆成短行，避免单行超长
function joinB64(parts) {
  return parts.join('');
}

